package com.chatregexfilter;

import static org.junit.Assert.assertEquals;
import java.awt.Color;
import org.junit.Test;

public class MarkLineTest
{
	@Test
	public void wrapsWholeLineInOneColour()
	{
		assertEquals("<col=ff0000>X hello</col>", ChatRegexFilterPlugin.markLine("hello", Color.RED));
	}

	@Test
	public void innerTagsAreRemovedSoColourHolds()
	{
		assertEquals("<col=ff0000>X You have been poisoned! run</col>",
			ChatRegexFilterPlugin.markLine("<col=00ff00>You have been poisoned!</col> run", Color.RED));
	}

	@Test
	public void nullIsSafe()
	{
		assertEquals("<col=ff0000>X </col>", ChatRegexFilterPlugin.markLine(null, Color.RED));
	}
}

package com.chatregexfilter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import net.runelite.client.util.Text;

/**
 * Compiles the configured regex list and decides whether a chat line should be hidden.
 * Pure Java, no client access, so it can be unit tested.
 */
public class LineFilter
{
	// a leading timestamp such as [12:34], [12:34:56] or [1:23 PM], optionally wrapped in a colour tag
	private static final Pattern LEADING_TIMESTAMP = Pattern.compile(
		"^\\s*(?:<col=[0-9a-fA-F]+>)?\\[\\d{1,2}:\\d{2}(?::\\d{2})?(?:\\s*[AaPp][Mm])?\\](?:</col>)?\\s*");

	private final List<Pattern> patterns;
	private final List<String> errors;

	public LineFilter(String text, boolean caseInsensitive)
	{
		List<Pattern> compiled = new ArrayList<>();
		List<String> problems = new ArrayList<>();
		if (text != null)
		{
			int lineNumber = 0;
			for (String raw : text.split("\\r?\\n"))
			{
				lineNumber++;
				String line = raw.trim();
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				int flags = caseInsensitive ? Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE : 0;
				try
				{
					compiled.add(Pattern.compile(line, flags));
				}
				catch (PatternSyntaxException e)
				{
					problems.add("line " + lineNumber + ": " + e.getDescription());
				}
			}
		}
		patterns = Collections.unmodifiableList(compiled);
		errors = Collections.unmodifiableList(problems);
	}

	public List<Pattern> getPatterns()
	{
		return patterns;
	}

	// human readable description of every line that failed to compile
	public List<String> getErrors()
	{
		return errors;
	}

	public boolean isEmpty()
	{
		return patterns.isEmpty();
	}

	// true when any pattern is found anywhere in the line
	public boolean matches(String line)
	{
		if (line == null || patterns.isEmpty())
		{
			return false;
		}
		for (Pattern pattern : patterns)
		{
			if (pattern.matcher(line).find())
			{
				return true;
			}
		}
		return false;
	}

	// the text a regex is run against: optional "Sender: " prefix, no timestamp, and optionally no <col>/<img> tags
	public static String normalize(String sender, String message, boolean stripTags)
	{
		if (message == null)
		{
			message = "";
		}
		String text = stripTimestamp(message);
		if (stripTags)
		{
			text = Text.removeTags(text);
		}
		if (sender != null && !sender.isEmpty())
		{
			String name = stripTags ? Text.removeTags(sender) : sender;
			text = name + ": " + text;
		}
		return text;
	}

	public static String stripTimestamp(String message)
	{
		if (message == null)
		{
			return "";
		}
		return LEADING_TIMESTAMP.matcher(message).replaceFirst("");
	}
}

package com.chatregexfilter;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.MessageNode;
import net.runelite.api.Point;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Chat Regex Filter",
	description = "Hides any chatbox line that matches your regular expressions, whatever chat type it came from",
	tags = {"chat", "filter", "regex", "hide", "spam", "clan", "broadcast", "mute"}
)
public class ChatRegexFilterPlugin extends Plugin
{
	// keep in sync with build.gradle
	public static final String VERSION = "1.0.0";

	private static final Logger log = LoggerFactory.getLogger(ChatRegexFilterPlugin.class);

	// the chatbox script fires this for every line it draws, with the message on the object stack
	private static final String CHAT_FILTER_CALLBACK = "chatFilterCheck";

	// the chatbox scroll area holds four dynamic children per line: sender, message, clan name, clan rank
	private static final int WIDGETS_PER_LINE = 4;
	private static final int MESSAGE_WIDGET_OFFSET = 1;

	private static final String COPY_RAW = "Copy raw text";
	private static final String COPY_FILTER = "Copy filter text";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatRegexFilterConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	private volatile LineFilter filter = new LineFilter("", true);

	@Provides
	ChatRegexFilterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatRegexFilterConfig.class);
	}

	@Override
	protected void startUp()
	{
		rebuild(false);
		clientThread.invoke(client::refreshChat);
		log.info("Chat Regex Filter started");
	}

	@Override
	protected void shutDown()
	{
		filter = new LineFilter("", true);
		clientThread.invoke(client::refreshChat);
		log.info("Chat Regex Filter stopped");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ChatRegexFilterConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		rebuild(true);
		// redraw so already visible lines pick up the new rules
		clientThread.invoke(client::refreshChat);
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!CHAT_FILTER_CALLBACK.equals(event.getEventName()))
		{
			return;
		}
		LineFilter current = filter;
		if (current.isEmpty())
		{
			return;
		}

		int[] intStack = client.getIntStack();
		int intStackSize = client.getIntStackSize();
		Object[] objectStack = client.getObjectStack();
		int objectStackSize = client.getObjectStackSize();
		if (intStackSize < 3 || objectStackSize < 1)
		{
			return;
		}

		// stack layout: [.., show flag, message type, message id] and [.., message text]
		int messageId = intStack[intStackSize - 1];
		Object text = objectStack[objectStackSize - 1];
		String message = text instanceof String ? (String) text : null;

		String sender = null;
		if (config.includeSender())
		{
			MessageNode node = client.getMessages().get(messageId);
			if (node != null)
			{
				sender = node.getName();
			}
		}

		String candidate = LineFilter.normalize(sender, message, config.stripTags());
		if (!current.matches(candidate))
		{
			return;
		}
		if (config.debugMode())
		{
			objectStack[objectStackSize - 1] = markLine(message, config.debugColor());
		}
		else
		{
			intStack[intStackSize - 3] = 0;
		}
	}

	// "X message" in one colour. Existing tags are removed so a </col> in the middle can't reset the colour
	static String markLine(String message, Color color)
	{
		String plain = Text.removeTags(message == null ? "" : message);
		return ColorUtil.wrapWithColorTag("X " + plain, color);
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!config.copyMenu())
		{
			return;
		}
		Widget scrollArea = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		Point mouse = client.getMouseCanvasPosition();
		if (scrollArea == null || scrollArea.isHidden() || mouse == null
			|| !scrollArea.getBounds().contains(mouse.getX(), mouse.getY()))
		{
			return;
		}
		Widget[] children = scrollArea.getDynamicChildren();
		if (children == null)
		{
			return;
		}
		Widget line = null;
		for (int i = MESSAGE_WIDGET_OFFSET; i < children.length; i += WIDGETS_PER_LINE)
		{
			Widget child = children[i];
			if (child != null && !child.isHidden() && child.contains(mouse))
			{
				line = child;
				break;
			}
		}
		if (line == null)
		{
			return;
		}

		// the widget holds what was drawn (after filtering and other plugins). Find the message behind it for the raw value
		String drawn = line.getText();
		MessageNode node = findNode(drawn);
		String raw = node != null ? node.getValue() : drawn;
		String sender = config.includeSender() && node != null ? node.getName() : null;
		String filterText = LineFilter.normalize(sender, raw, config.stripTags());

		client.getMenu().createMenuEntry(1)
			.setOption(COPY_FILTER)
			.setTarget("")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> copyToClipboard(filterText));
		client.getMenu().createMenuEntry(1)
			.setOption(COPY_RAW)
			.setTarget("")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> copyToClipboard(raw));
	}

	// the drawn text may carry a timestamp or our debug X in front, so match a message whose plain text ends the line.
	// Longest match wins, newest on a tie
	private MessageNode findNode(String drawn)
	{
		String plainDrawn = Text.removeTags(drawn == null ? "" : drawn);
		MessageNode best = null;
		int bestLength = 0;
		for (MessageNode node : client.getMessages())
		{
			String value = node.getValue();
			if (value == null)
			{
				continue;
			}
			String plain = Text.removeTags(value);
			if (plain.isEmpty() || !plainDrawn.endsWith(plain))
			{
				continue;
			}
			if (plain.length() > bestLength || (plain.length() == bestLength && best != null && node.getId() > best.getId()))
			{
				best = node;
				bestLength = plain.length();
			}
		}
		return best;
	}

	private static void copyToClipboard(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
	}

	private void rebuild(boolean announce)
	{
		LineFilter next = new LineFilter(config.patterns(), config.caseInsensitive());
		filter = next;
		for (String error : next.getErrors())
		{
			log.warn("Chat Regex Filter: invalid pattern, {}", error);
		}
		if (announce && config.reportInvalid() && !next.getErrors().isEmpty()
			&& client.getGameState() == GameState.LOGGED_IN)
		{
			String summary = "Chat Regex Filter: " + next.getErrors().size()
				+ (next.getErrors().size() == 1 ? " pattern is" : " patterns are")
				+ " not valid regex and will be ignored (" + next.getErrors().get(0) + ")";
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(summary)
				.build());
		}
	}
}

package com.chatregexfilter;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(ChatRegexFilterConfig.GROUP)
public interface ChatRegexFilterConfig extends Config
{
	String GROUP = "chatregexfilter";

	@ConfigSection(
		name = "Debug",
		description = "Tools for checking what the patterns match",
		position = 10,
		closedByDefault = true
	)
	String debugSection = "debug";

	@ConfigItem(
		keyName = "patterns",
		name = "Patterns",
		description = "Regular expressions, one per line. Any chatbox line containing a match is hidden. Lines starting with # are ignored",
		position = 0
	)
	default String patterns()
	{
		return "";
	}

	@ConfigItem(
		keyName = "caseInsensitive",
		name = "Ignore case",
		description = "Match regardless of upper or lower case",
		position = 1
	)
	default boolean caseInsensitive()
	{
		return true;
	}

	@ConfigItem(
		keyName = "stripTags",
		name = "Strip formatting tags",
		description = "Remove <col=...> and <img=...> tags before matching, so patterns see the plain text you read in the chatbox",
		position = 2
	)
	default boolean stripTags()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeSender",
		name = "Include sender name",
		description = "Match against \"Name: message\" instead of just the message, so a pattern can target a particular player",
		position = 3
	)
	default boolean includeSender()
	{
		return false;
	}

	@ConfigItem(
		keyName = "reportInvalid",
		name = "Report invalid patterns",
		description = "Print a chatbox message when a line in the pattern list is not a valid regular expression",
		position = 4
	)
	default boolean reportInvalid()
	{
		return true;
	}

	@ConfigItem(
		keyName = "debugMode",
		name = "Mark instead of hide",
		description = "Leave matching lines in the chatbox, prefixed with an X and coloured, so you can see what would be hidden",
		position = 0,
		section = debugSection
	)
	default boolean debugMode()
	{
		return false;
	}

	@ConfigItem(
		keyName = "debugColor",
		name = "Mark colour",
		description = "Colour used for marked lines when Mark instead of hide is on",
		position = 1,
		section = debugSection
	)
	default Color debugColor()
	{
		return Color.RED;
	}

	@ConfigItem(
		keyName = "copyMenu",
		name = "Right-click copy",
		description = "Add \"Copy raw text\" and \"Copy filter text\" to the right-click menu on any chatbox line, to paste into your patterns",
		position = 2,
		section = debugSection
	)
	default boolean copyMenu()
	{
		return false;
	}
}
